INSERT INTO cases (case_id, case_title, normalized_case_title, case_number, case_type, sector, sub_sector, primary_mode, secondary_modes, case_date, investigation_date, suspect_date, indictment_date, prosecution_date, trial_start_date, verdict_date, final_decision_date, execution_date, era_pemerintahan, summary, verification_status, confidence_level, possible_duplicate, needs_manual_review, verification_note) VALUES ('cas-de-unie-roeslan-1956', 'Penyelidikan Dugaan Korupsi Devisa dan Barter Percetakan De Unie', 'penyelidikan dugaan korupsi devisa dan barter percetakan de unie', 'SP-Kejagung/PM-1956', 'Tindak Pidana Korupsi', 'Penyalahgunaan Anggaran', 'Devisa & Pengadaan Percetakan Luar Negeri', 'Penyalahgunaan Anggaran', '{"Konflik Kepentingan","Pengadaan Barang/Jasa"}', '1956-08-01', '1956-08-13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Era Kemerdekaan & Orde Lama (1945 - 1966)', 'Penyelidikan Polisi Militer dan Jaksa Agung Soeprapto terhadap NV Percetakan De Unie terkait barter devisa cetak uang dan surat suara yang menyeret Menteri Luar Negeri Roeslan Abdulgani sebelum dibebaskan oleh komisi kabinet.', 'VERIFIED_PRIMARY', 'high', FALSE, FALSE, 'Pemeriksaan dihentikan setelah Komisi Penyelidik Khusus Kabinet Ali Sastroamidjojo II menyatakan Menlu Roeslan Abdulgani tidak terbukti menikmati keuntungan pribadi.');
INSERT INTO cases (case_id, case_title, normalized_case_title, case_number, case_type, sector, sub_sector, primary_mode, secondary_modes, case_date, investigation_date, suspect_date, indictment_date, prosecution_date, trial_start_date, verdict_date, final_decision_date, execution_date, era_pemerintahan, summary, verification_status, confidence_level, possible_duplicate, needs_manual_review, verification_note) VALUES ('cas-jmd-bank-sentral-1966', 'Korupsi Devisa dan Subversi Ekonomi Menteri Perbankan Teuku Jusuf Muda Dalam', 'korupsi devisa dan subversi ekonomi menteri perbankan teuku jusuf muda dalam', '4001/1966 Pid.Subv', 'Tindak Pidana Korupsi', 'Perbankan', 'Bank Sentral & Devisa Impor', 'Penyalahgunaan Anggaran', '{"Suap","Gratifikasi","Penggelapan"}', '1966-03-18', '1966-04-01', '1966-04-10', '1966-08-15', '1966-08-30', '1966-08-20', '1966-09-09', '1966-09-09', NULL, 'Era Kemerdekaan & Orde Lama (1945 - 1966)', 'Penyalahgunaan wewenang pengelolaan devisa negara, pengeluaran izin deferred payment, penggelapan dana revolusi Rp97 miliar (uang lama), dan suap lisensi impor oleh Menteri Urusan Bank Sentral Teuku Jusuf Muda Dalam.', 'VERIFIED_PRIMARY', 'high', FALSE, FALSE, 'Divonis pidana mati oleh Pengadilan Negeri Istimewa Jakarta tanggal 9 September 1966. Terdakwa meninggal karena sakit dalam penahanan di RS Militer Cimahi pada 26 Agustus 1976 sebelum eksekusi hukuman mati terlaksana.');
INSERT INTO cases (case_id, case_title, normalized_case_title, case_number, case_type, sector, sub_sector, primary_mode, secondary_modes, case_date, investigation_date, suspect_date, indictment_date, prosecution_date, trial_start_date, verdict_date, final_decision_date, execution_date, era_pemerintahan, summary, verification_status, confidence_level, possible_duplicate, needs_manual_review, verification_note) VALUES ('cas-dolog-kaltim-budiadji-1976', 'Korupsi Pengadaan Beras dan Kas Dolog Kalimantan Timur Budiadji', 'korupsi pengadaan beras dan kas dolog kalimantan timur budiadji', '12/Pid/1977', 'Tindak Pidana Korupsi', 'Penyalahgunaan Anggaran', 'Bulog & Logistik Pangan Daerah', 'Penyalahgunaan Anggaran', '{"Penggelapan","Pengadaan Barang/Jasa"}', '1976-09-10', '1976-10-15', '1976-11-01', '1977-01-20', '1977-05-18', '1977-02-05', '1977-06-25', '1977-06-25', '1977-07-10', 'Era Orde Baru (1966 - 1998)', 'Manipulasi pembukuan kas Dolog Kaltim, penggelapan beras jatah pegawai dan ABRI, serta penyalahgunaan dana kas daerah senilai Rp7,607 miliar oleh Kepala Dolog Kaltim Kolonel Budiadji.', 'VERIFIED_PRIMARY', 'high', FALSE, FALSE, 'PN Samarinda menjatuhkan vonis Penjara Seumur Hidup. Melalui Grasi Presiden No. 25/G/1980, pidana diubah menjadi 20 tahun penjara, dan yang bersangkutan bebas bersyarat pada 1988.');
INSERT INTO cases (case_id, case_title, normalized_case_title, case_number, case_type, sector, sub_sector, primary_mode, secondary_modes, case_date, investigation_date, suspect_date, indictment_date, prosecution_date, trial_start_date, verdict_date, final_decision_date, execution_date, era_pemerintahan, summary, verification_status, confidence_level, possible_duplicate, needs_manual_review, verification_note) VALUES ('cas-bank-duta-dicky-1990', 'Penyimpangan Valuta Asing dan Penggelapan Dana Kas Bank Duta', 'penyimpangan valuta asing dan penggelapan dana kas bank duta', 'Kasasi MA 26 Mei 1992', 'Tindak Pidana Korupsi', 'Perbankan', 'Valuta Asing & Perbankan Swasta Yayasan', 'Penggelapan', '{"Penyalahgunaan Anggaran"}', '1990-09-04', '1990-09-20', '1990-10-15', '1991-03-05', '1991-07-10', '1991-03-25', '1991-08-19', '1992-05-26', '1992-06-15', 'Era Orde Baru (1966 - 1998)', 'Spekulasi valas ilegal offshore tanpa kontrol risiko yang mengakibatkan Bank Duta mengalami kerugian USD 419,6 juta menjelang IPO, ditutup bailout konsorsium yayasan Soeharto.', 'VERIFIED_PRIMARY', 'high', FALSE, FALSE, 'Dirut Dicky Iskandar Di Nata divonis 8 tahun penjara oleh PN Jakarta Pusat dan dikuatkan Kasasi MA pada 26 Mei 1992, disertai kewajiban ganti rugi Rp811 miliar.');
INSERT INTO cases (case_id, case_title, normalized_case_title, case_number, case_type, sector, sub_sector, primary_mode, secondary_modes, case_date, investigation_date, suspect_date, indictment_date, prosecution_date, trial_start_date, verdict_date, final_decision_date, execution_date, era_pemerintahan, summary, verification_status, confidence_level, possible_duplicate, needs_manual_review, verification_note) VALUES ('cas-bapindo-eddy-tansil-1994', 'Pembobolan Kredit Letter of Credit (L/C) Bapindo oleh Golden Key Group', 'pembobolan kredit letter of credit lc bapindo oleh golden key group', 'Putusan PN Jakpus 15 Agustus 1994', 'Tindak Pidana Korupsi', 'Perbankan', 'Kredit Bank BUMN & Industri Petrokimia', 'Penyalahgunaan Anggaran', '{"Suap","Penggelapan"}', '1994-02-14', '1994-02-20', '1994-02-25', '1994-04-20', '1994-07-28', '1994-05-11', '1994-08-15', '1995-06-20', NULL, 'Era Orde Baru (1966 - 1998)', 'Pencairan kredit fiktif dan Letter of Credit (L/C) tanpa agunan memadai dari Bank Pembangunan Indonesia (Bapindo) kepada grup usaha Golden Key senilai USD 430 juta (setara Rp1,3 triliun).', 'VERIFIED_PRIMARY', 'high', FALSE, FALSE, 'Eddy Tansil divonis 17 tahun penjara, denda Rp30 juta, dan uang pengganti Rp500 miliar pada 15 Agustus 1994. Pada 4 Mei 1996 melarikan diri dari LP Cipinang dan berstatus buronan.');
INSERT INTO cases (case_id, case_title, normalized_case_title, case_number, case_type, sector, sub_sector, primary_mode, secondary_modes, case_date, investigation_date, suspect_date, indictment_date, prosecution_date, trial_start_date, verdict_date, final_decision_date, execution_date, era_pemerintahan, summary, verification_status, confidence_level, possible_duplicate, needs_manual_review, verification_note) VALUES ('cas-yayasan-supersemar-soeharto', 'Gugatan Perdata Perbuatan Melawan Hukum Penyelewengan Dana Yayasan Supersemar', 'gugatan perdata perbuatan melawan hukum penyelewengan dana yayasan supersemar', '140 PK/Pdt/2015 jo. 2896 K/Pdt/2009', 'Tindak Pidana Korupsi', 'Penyalahgunaan Anggaran', 'Yayasan Kepresidenan & Dana BUMN', 'Penyalahgunaan Anggaran', '{"Konflik Kepentingan"}', '1998-05-21', '1998-12-01', '2000-08-08', '2007-07-09', NULL, '2007-08-14', '2008-03-27', '2015-07-08', '2018-11-19', 'Era Orde Baru (1966 - 1998)', 'Penyelewengan dana beasiswa Yayasan Supersemar yang bersumber dari laba bersih bank-bank BUMN untuk dipinjamkan dan disetor modal ke grup bisnis swasta terafiliasi (Bank Duta, PT Sempati Air, PT Kiani Sari).', 'VERIFIED_PRIMARY', 'high', FALSE, FALSE, 'Gugatan perdata PMH diajukan Kejaksaan Agung RI mewakili negara setelah penuntutan pidana terhadap H.M. Soeharto dihentikan (SKP3 karena sakit permanen). Putusan PK MA No. 140 PK/Pdt/2015 menghukum Yayasan Supersemar membayar ganti rugi USD 315 juta dan Rp139,2 miliar (total setara Rp4,4 triliun).');
